import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int cols = 4 * n;
        int[][] mat = new int[4][cols];
        for (int r = 0; r < 4; r++)
            for (int c = 0; c < cols; c++) mat[r][c] = (int) nextLong();
        int[] missing = new int[n];
        Integer[] order = new Integer[n];
        for (int b = 0; b < n; b++) {
            int sum = 0;
            for (int r = 0; r < 4; r++)
                for (int c = 0; c < 4; c++)
                    if (mat[r][4 * b + c] != -1) sum += mat[r][4 * b + c];
            missing[b] = 136 - sum;
            order[b] = b;
        }
        Arrays.sort(order, Comparator.comparingInt(b -> missing[b]));  // stable merge sort
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < 4; r++) {
            for (int j = 0; j < n; j++) {
                int b = order[j];
                for (int c = 0; c < 4; c++) {
                    int x = mat[r][4 * b + c];
                    if (j > 0 || c > 0) out.append(' ');
                    out.append(x == -1 ? missing[b] : x);
                }
            }
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	cols := 4 * n
	var mat [4][]int
	for r := range mat {
		mat[r] = make([]int, cols)
		for c := range mat[r] {
			mat[r][c] = int(nextInt())
		}
	}
	missing := make([]int, n)
	order := make([]int, n)
	for b := 0; b < n; b++ {
		sum := 0
		for r := 0; r < 4; r++ {
			for c := 0; c < 4; c++ {
				if v := mat[r][4*b+c]; v != -1 {
					sum += v
				}
			}
		}
		missing[b] = 136 - sum
		order[b] = b
	}
	slices.SortStableFunc(order, func(x, y int) int { return missing[x] - missing[y] })
	out := []byte{}
	for r := 0; r < 4; r++ {
		for j, b := range order {
			for c := 0; c < 4; c++ {
				x := mat[r][4*b+c]
				if x == -1 {
					x = missing[b]
				}
				if j > 0 || c > 0 {
					out = append(out, ' ')
				}
				out = strconv.AppendInt(out, int64(x), 10)
			}
		}
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
